function setup() {
  let W = windowWidth, H = windowHeight;
  let theRatio = 3/2;
  let w = 400;
  createCanvas(w, w*theRatio);
  // noLoop() removed for animation
  noStroke();
}

function draw() {
  let buff = createGraphics(width*2, height*2);
  buff.noStroke();

  let palettes = [["#abcd5e", "#14976b", "#2b67af", "#62b6de", "#f589a3", "#ef562f", "#fc8405", "#f9d531"], ["#fffbe6", "#050505"]];
  let factor = palettes[0].length;

  let x = 0, i = 0;
  let _wG_1 = 0; while ((x < 2*width) && ++_wG_1 < 20000) {
    let colors = palettes[(i++)%palettes.length];
    let j = floor(random(colors.length));
    let n = ~~random(1, 5) + random([0, 1]);
    let m = (j%2==0) ? 3 : 0;
    let sy = height/pow(2, n + m);
    let sx = pow(2, n);
    let y = 0;
    let _wG_2 = 0; while ((y < 2*height) && ++_wG_2 < 20000) {
      buff.fill(colors[(j++)%colors.length]);
      buff.rect(x, y, sx, sy);
      y += sy;
    }
    x += sx;
  }


  let maxOffset = 32;
  let offRed = random([0, maxOffset]);
  let offGreen = random([0, maxOffset]);
  let offBlue = random([0, maxOffset]);
  buff.loadPixels();
  let den = buff.pixelDensity();
  let maxNoise = 32;
  var n = 4 * (buff.width * den) * (buff.height * den);
  for (let i = 0; i < n; i += 4) {
    if (random() < 0.000001) {
      offRed = random([0, maxOffset]);
      offGreen = random([0, maxOffset]);
      offBlue = random([0, maxOffset]);
    }
    buff.pixels[i] = buff.pixels[i+offRed] + random(-1, 1)*maxNoise;
    buff.pixels[i + 1] = buff.pixels[i+1+offGreen] + random(-1, 1)*maxNoise;
    buff.pixels[i + 2] = buff.pixels[i+2+offBlue] + random(-1, 1)*maxNoise;
  }
  buff.updatePixels();

  imageMode(CENTER);
  translate(width/2, height/2);
  rotate(PI/2 - atan2(height, width));
  image(buff, 0, 0);
}
